import type { Scene, TabId, Approvals } from "./types";

/**
 * Derived timing.
 *
 * A scene stores duration and may store explicit placement after a timeline
 * drag. Runtime, effective starts, word timings, act splits and every timecode
 * are recomputed from those inputs, so the user never manually syncs.
 */

/** m:ss (compact display for durations). */
export function fmt(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

/** HH:MM:SS:FF — fixed-width NLE timecode. */
export function timecode(seconds: number, fps = 24): string {
  const totalFrames = Math.max(0, Math.round(seconds * fps));
  const h = Math.floor(totalFrames / (60 * 60 * fps));
  const m = Math.floor((totalFrames % (60 * 60 * fps)) / (60 * fps));
  const s = Math.floor((totalFrames % (60 * fps)) / fps);
  const f = totalFrames % fps;
  return [h, m, s, f].map((part) => String(part).padStart(2, "0")).join(":");
}

/** Two-digit scene number, 1-indexed. */
export function num(index: number): string {
  return String(index + 1).padStart(2, "0");
}

/** The scenes that are actually in the video. */
export function enabled(scenes: Scene[]): Scene[] {
  return scenes.filter((scene) => !scene.disabled);
}

/**
 * Runtime of the cut, which is the sum of the beats that will play.
 *
 * A disabled beat contributes nothing. It keeps its narration, its visuals and
 * its place in the order — it is simply not in the video, so counting its
 * seconds would make the header disagree with what exports.
 */
export function total(scenes: Scene[]): number {
  return scenes.reduce((a, s) => (s.disabled ? a : a + s.dur), 0);
}

export function starts(scenes: Scene[]): number[] {
  let acc = 0;
  return scenes.map((s) => {
    const v = acc;
    if (!s.disabled) acc += s.dur;
    return v;
  });
}

export function totalAll(scenes: Scene[]): number {
  return scenes.reduce((a, s) => a + s.dur, 0);
}

export function startsAll(scenes: Scene[]): number[] {
  let acc = 0;
  return scenes.map((s) => {
    const v = acc;
    acc += s.dur;
    return v;
  });
}

export function startsOf(durations: number[]): number[] {
  let acc = 0;
  return durations.map((seconds) => {
    const at = acc;
    acc += seconds;
    return at;
  });
}

export function wordCount(text: string): number {
  const t = text.trim();
  return t ? t.split(/\s+/).length : 0;
}

export function scriptWordCount(scenes: Scene[]): number {
  return scenes.reduce((a, s) => a + wordCount(s.narration), 0);
}

/** Words per minute decides the pace label. */
/**
 * How fast a passage reads, from words against seconds.
 *
 * Split out from `pace` so the connected Script stage can ask the same
 * question of an artifact payload, which is not a `Scene`. One threshold, two
 * callers — the alternative was the same 165 written twice and free to drift.
 */
export function paceOf(words: number, seconds: number): "brisk" | "measured" {
  if (seconds <= 0) return "measured";
  return words / (seconds / 60) > 165 ? "brisk" : "measured";
}

export function pace(scene: Scene): "brisk" | "measured" {
  return paceOf(wordCount(scene.narration), scene.dur);
}

/** Which scene is on screen at time t, including disabled scenes. */
export function sceneAtAll(scenes: Scene[], t: number): number {
  const st = startsAll(scenes);
  for (let i = st.length - 1; i >= 0; i--) if (t >= st[i] && t < st[i] + scenes[i].dur) return i;
  for (let i = st.length - 1; i >= 0; i--) if (t >= st[i]) return i;
  return 0;
}

export interface TimedWord {
  t: string;
  /** Absolute start time in the full runtime. */
  at: number;
  /** How long this word is on screen. */
  per: number;
}

/** A scene's duration spread evenly across its tokens. */
export function timedWords(scene: Scene, start: number): TimedWord[] {
  const toks = scene.narration.trim().split(/\s+/).filter(Boolean);
  if (!toks.length) return [];
  const per = scene.dur / toks.length;
  return toks.map((t, i) => ({ t, at: start + i * per, per }));
}

/* ------------------------------------------------------------------
   Acts — three, split proportionally across the beat list
   ------------------------------------------------------------------ */

export interface Act {
  label: string;
  name: string;
  /** Indices into the scene array. */
  beats: number[];
  dur: number;
  meta: string;
  widthPct: string;
}

export function acts(scenes: Scene[]): Act[] {
  const n = scenes.length;
  const cut1 = Math.max(1, Math.round(n * 0.25));
  const cut2 = Math.max(cut1 + 1, Math.round(n * 0.75));
  const t = total(scenes) || 1;
  const range = (from: number, to: number) =>
    Array.from({ length: Math.max(0, to - from) }, (_, i) => from + i);

  return (
    [
      { label: "ACT I", name: "The problem", beats: range(0, cut1) },
      { label: "ACT II", name: "The mechanism", beats: range(cut1, cut2) },
      { label: "ACT III", name: "The payoff", beats: range(cut2, n) },
    ] as const
  )
    .filter((a) => a.beats.length)
    .map((a) => {
      const dur = a.beats.reduce((acc, i) => acc + scenes[i].dur, 0);
      return {
        ...a,
        beats: [...a.beats],
        dur,
        meta: `${a.beats.length} beat${a.beats.length > 1 ? "s" : ""} · ${fmt(dur)}`,
        widthPct: `${((dur / t) * 100).toFixed(2)}%`,
      };
    });
}

/** Indices of Act II — used by the Producer's "tighten act II" action. */
export function actTwoRange(scenes: Scene[]): [number, number] {
  const n = scenes.length;
  const cut1 = Math.max(1, Math.round(n * 0.25));
  const cut2 = Math.max(cut1 + 1, Math.round(n * 0.75));
  return [cut1, cut2];
}

/* ------------------------------------------------------------------
   Stage gating
   ------------------------------------------------------------------ */

/** Nav level required to open each stage. */
export const NAV_LEVEL: Record<TabId, number> = {
  overview: 0,
  plan: 1,
  script: 2,
  edit: 5,
};

/** A stage unlocks only when the previous one is approved. */
export function unlockLevel(a: Approvals): number {
  if (a.script) return 5;
  if (a.plan) return 2;
  if (a.understanding) return 1;
  return 0;
}

export function isLocked(tab: TabId, a: Approvals): boolean {
  return NAV_LEVEL[tab] > unlockLevel(a);
}

/* ------------------------------------------------------------------ *
 * Easing
 *
 * The interaction thesis allows exactly one curve, and CSS gets it from
 * `--ease-decode`. These are its scalar form, for progress driven in JS
 * (scroll scrub, scene playheads). Keep them here so the two can never
 * drift apart — three private copies is how a "single curve" quietly
 * becomes three.
 * ------------------------------------------------------------------ */

/** Clamp to the 0–1 progress domain. */
export const clamp01 = (n: number) => Math.max(0, Math.min(1, n));

/**
 * Round to 6 decimals. Transcendental functions (`sin`, `cos`, `pow`) are not
 * bit-identical between Node's libm and the browser's, so a value derived from
 * one renders as e.g. `0.7895637203045311` on the server and
 * `0.7895637203045313` on the client — different strings, and React reports a
 * hydration mismatch. Quantising at the source makes every derived attribute
 * agree. Six decimals is far finer than any pixel or opacity step.
 */
export const q6 = (n: number) => Math.round(n * 1e6) / 1e6;

/** `Math.sin`, made deterministic across server and client. */
export const sin = (x: number) => q6(Math.sin(x));

/** `Math.cos`, made deterministic across server and client. */
export const cos = (x: number) => q6(Math.cos(x));

/** Ease-out cubic — the scalar twin of `cubic-bezier(0.22, 1, 0.36, 1)`. */
export const ease = (t: number) => q6(1 - Math.pow(1 - clamp01(t), 3));

/** Progress inside a sub-window of a larger 0–1 range. */
export const seg = (p: number, from: number, to: number) =>
  clamp01((p - from) / Math.max(0.0001, to - from));

/* ------------------------------------------------------------------
   What the room notices
   ------------------------------------------------------------------ */

/**
 * The approved runtime target, in seconds.
 *
 * The store keeps it as the creator-facing string the brief was written in
 * ("5 min"), because that is what the Understanding stage shows back. Parsing
 * it here rather than storing a second number keeps the two from disagreeing.
 */
export function targetSeconds(runtime: string): number | null {
  const match = /^(\d+)\s*min/.exec(runtime.trim());
  return match ? Number(match[1]) * 60 : null;
}

export interface Observation {
  id: string;
  /** What is true, said plainly and with the numbers in it. */
  text: string;
  /** What it costs, or what could be done about it. */
  detail: string;
  /** `attention` is something that will bite. `note` is worth knowing. */
  tone: "note" | "attention";
}

/** A cut may drift this far from its target before it is worth mentioning. */
const RUNTIME_TOLERANCE = 0.05;

/**
 * Thresholds the Director is already held to, reused here so the room and the
 * department that wrote the plan cannot disagree about what "too short" means.
 * See `departments/architect/SKILL.md`: under fifteen seconds is usually a
 * fragment of its neighbour, over ninety is usually two beats.
 */
const SHORT_SCENE = 15;
const LONG_SCENE = 90;

/**
 * What the Production room can see without being asked.
 *
 * Every one of these is derived at call time from `dur` and the narration, the
 * same inputs the timeline and the header read. Nothing is stored, so retiming
 * a scene changes what the room says about it on the next render — there is no
 * staleness to manage and nothing to invalidate.
 */
export function observations(scenes: Scene[], runtime: string): Observation[] {
  const found: Observation[] = [];
  if (scenes.length === 0) return found;

  const st = starts(scenes);
  const cut = total(scenes);
  const target = targetSeconds(runtime);

  if (target !== null) {
    const drift = cut - target;
    if (Math.abs(drift) > target * RUNTIME_TOLERANCE) {
      const over = drift > 0;
      found.push({
        id: "runtime",
        text: over
          ? `The cut runs ${fmt(cut)} against the ${fmt(target)} you asked for.`
          : `The cut runs ${fmt(cut)}, ${fmt(-drift)} under the ${fmt(target)} you asked for.`,
        detail: over
          ? `${fmt(drift)} over. I can take it out of the longest scenes without touching what they teach.`
          : "There is room to let a beat breathe, or to add one the plan left out.",
        tone: over ? "attention" : "note",
      });
    }
  }

  // The scene reading fastest, named with where it is, so it can be found.
  const brisk = scenes
    .map((scene, index) => ({ scene, index, rate: wordCount(scene.narration) / (scene.dur / 60) }))
    .filter((item) => pace(item.scene) === "brisk")
    .sort((a, b) => b.rate - a.rate)[0];
  if (brisk) {
    found.push({
      id: "pace",
      text: `Scene ${num(brisk.index)} at ${fmt(st[brisk.index])} reads fast — ${wordCount(
        brisk.scene.narration,
      )} words in ${fmt(brisk.scene.dur)}.`,
      detail: "Either it needs more seconds or the narration needs fewer words.",
      tone: "attention",
    });
  }

  const short = scenes.findIndex((scene) => scene.dur < SHORT_SCENE);
  if (short >= 0) {
    found.push({
      id: "short",
      text: `Scene ${num(short)} is only ${fmt(scenes[short].dur)} long.`,
      detail: "Under fifteen seconds a beat usually belongs to the one beside it.",
      tone: "note",
    });
  }

  const long = scenes.findIndex((scene) => scene.dur > LONG_SCENE);
  if (long >= 0) {
    found.push({
      id: "long",
      text: `Scene ${num(long)} runs ${fmt(scenes[long].dur)}.`,
      detail: "Past ninety seconds a beat is usually two ideas that could be split.",
      tone: "note",
    });
  }

  return found;
}
